import React, { useState, useEffect } from 'react';
import { Auth } from 'aws-amplify';
import { useNavigate } from 'react-router-dom';
import {
    Container,
    Typography,
    Paper,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    CircularProgress,
    Alert,
    Box
} from '@mui/material';
import axios from 'axios';

const API_URL = 'https://qym7ixny0k.execute-api.us-east-1.amazonaws.com/dev';

// Crear una instancia de axios con configuración base
const api = axios.create({
    baseURL: API_URL,
    timeout: 10000,
    headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json'
    }
});

const UserList = () => {
    const [users, setUsers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const navigate = useNavigate();

    useEffect(() => {
        fetchUsers();
    }, []);

    const fetchUsers = async () => {
        try {
            setLoading(true);
            setError('');

            // Obtener la sesión actual
            const session = await Auth.currentSession();
            const token = session.getIdToken().getJwtToken();

            // Configurar la petición exactamente como en Postman
            const config = {
                url: `${API_URL}/users`,
                method: 'GET',
                timeout: 0,
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`
                }
            };

            console.log('Configuración de la petición:', config);

            const response = await axios(config);
            console.log('Respuesta completa:', response);

            if (response.data) {
                setUsers(response.data);
            } else {
                throw new Error('No se recibieron datos de la API');
            }
        } catch (err) {
            console.error('Error completo:', err);
            console.error('Error response:', err.response);
            console.error('Error request:', err.request);
            console.error('Error config:', err.config);

            if (err.message === 'No current user') {
                setError('Sesión expirada. Por favor, vuelva a iniciar sesión.');
                setTimeout(() => {
                    navigate('/login');
                }, 2000);
            } else if (err.response) {
                // El servidor respondió con un código de error
                setError(`Error del servidor: ${err.response.status} - ${err.response.data?.message || 'Error desconocido'}`);
            } else if (err.request) {
                // La petición fue hecha pero no se recibió respuesta
                setError('No se pudo conectar con el servidor. Por favor, verifica tu conexión a internet.');
            } else {
                setError(err.message || 'Error al obtener los usuarios');
            }
        } finally {
            setLoading(false);
        }
    };

    if (loading) {
        return (
            <Container>
                <Box sx={{ display: 'flex', justifyContent: 'center', mt: 4 }}>
                    <CircularProgress />
                </Box>
            </Container>
        );
    }

    return (
        <Container>
            <Typography variant="h4" component="h1" gutterBottom sx={{ mt: 4 }}>
                Lista de Usuarios
            </Typography>

            {error && (
                <Alert severity="error" sx={{ mb: 2 }}>
                    {error}
                </Alert>
            )}

            <TableContainer component={Paper}>
                <Table>
                    <TableHead>
                        <TableRow>
                            <TableCell>Nombre</TableCell>
                            <TableCell>Email</TableCell>
                            <TableCell>Teléfono</TableCell>
                        </TableRow>
                    </TableHead>
                    <TableBody>
                        {users.map((user) => (
                            <TableRow key={user.id}>
                                <TableCell>{user.name}</TableCell>
                                <TableCell>{user.email}</TableCell>
                                <TableCell>{user.phone || '-'}</TableCell>
                            </TableRow>
                        ))}
                        {users.length === 0 && (
                            <TableRow>
                                <TableCell colSpan={3} align="center">
                                    No hay usuarios registrados
                                </TableCell>
                            </TableRow>
                        )}
                    </TableBody>
                </Table>
            </TableContainer>
        </Container>
    );
};

export default UserList;
